export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity;
  const T = u / g, H = u * u / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * T));
  const yT = u * t - g * t * t / 2;
  const vT = u - g * t;
  const open = t >= T - 1e-9;
  const yD = open ? yT : H;
  const vD = open ? -g * (t - T) : 0;
  const aD = open ? -g : 0;
  const base = 370, k = 140, R = 26;
  const Y = h => base - h * k;
  const o = [];
  const lanes = [[20, 'toss', 'Toss'], [330, 'drop', 'Drop']];
  const atTop = Math.abs(t - T) < 0.005;
  const end = t >= 2 * T - 0.005;
  const sT = t < 0.005 ? 'At launch' : atTop ? 'At the top' : end ? 'At launch height' : t < T ? 'Rising' : 'Falling';
  const sD = end ? 'At launch height' : !open ? 'Held in place' : (t - T < 0.05 ? 'Just released' : 'Falling together');
  const st = [sT, sD];
  lanes.forEach((l, i) => {
    o.push(...sdk.panel({ id: 'lane.' + l[1], x: l[0], y: 40, w: 290, h: 360, title: l[2], state: st[i], role: i ? 'warning' : 'input' }));
    o.push(...sdk.groundMark('mark.' + l[1], l[0] + 190, 385, 60));
  });
  const cxT = 210, cxD = 520;
  o.push(sdk.circle('ball.toss', cxT, Y(yT), R, { role: 'input' }));
  o.push(sdk.circle('ball.drop', cxD, Y(yD), R, { role: 'warning' }));
  if (open) o.push(sdk.circle('outline.drop', cxD, Y(H), R, { role: 'neutral', opacity: 0.25 }));
  o.push(...sdk.gate('gate.drop', cxD, Y(H) + 16, { open, w: 36 }));
  o.push(...sdk.vector('vec.v.toss', { x: cxT - 24, y: Y(yT) }, { value: vT, direction: 'up' }, { scale: 10, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a.toss', { x: cxT + 24, y: Y(yT) }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.vector('vec.v.drop', { x: cxD - 24, y: Y(yD) }, { value: vD, direction: 'up' }, { scale: 10, label: 'v', role: 'input' }));
  o.push(...sdk.vector('vec.a.drop', { x: cxD + 24, y: Y(yD) }, { value: aD, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...[sdk.callout(28, 70, ['v = ' + sdk.format(vT, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²'], { id: 'callout.toss' })].flat());
  o.push(...[sdk.callout(338, 70, ['v = ' + sdk.format(vD, 2) + ' m/s', 'a = ' + sdk.format(aD, 1) + ' m/s²'], { id: 'callout.drop' })].flat());
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [
      { id: 'tossedVelocity', value: vT }, { id: 'tossedAcceleration', value: -g },
      { id: 'dropVelocity', value: vD }, { id: 'dropAcceleration', value: aD }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vT, tossedAcceleration: -g, tossedHeight: yT, dropVelocity: vD, dropAcceleration: aD, dropHeight: yD }
  };
}
